#!/usr/bin/env python3# -*- coding: utf-8 -*-"""Replica-level glass-transition analysis workflow.This module orchestrates the complete Tg analysis pipeline for onecompleted molecular-dynamics simulation.Workflow--------1. Load simulation.2. Assign nominal temperatures.3. Generate chain-level structural descriptors.4. Optimise PCA dimensionality.5. Calculate the final PCA representation.6. Optimise DBSCAN parameters.7. Perform final DBSCAN clustering.8. Construct the temperature-dependent structural response.9. Fit the glass-transition model.10. Build reusable replica-level conformational-state data.11. Save machine-readable replica outputs.12. Optionally generate replica-level figures and a text report.All outputs belonging to one replica are stored beneath::    simulations/<simulation_name>/analysis/tg_analysis/The resulting files are intended to provide the inputs for subsequentmulti-replica / system-level analysis."""from __future__ import annotationsfrom pathlib import Pathimport jsonimport sysimport matplotlib.pyplot as pltimport numpy as npimport pandas as pd# =============================================================================# Package import support# =============================================================================# Allow direct execution:##     python workflow.py## while also supporting:##     python -m iphasimulator.analysis.tg_analysis.workflowif __package__ in (None, ""):    SRC_DIRECTORY = (        Path(__file__)        .resolve()        .parents[3]    )    if str(SRC_DIRECTORY) not in sys.path:        sys.path.insert(            0,            str(SRC_DIRECTORY),        )# =============================================================================# Analysis imports# =============================================================================from iphasimulator.analysis.simulation_loader import (    load_simulation,)from iphasimulator.analysis.descriptors import (    calculate_all_chain_distance_descriptors,)from iphasimulator.analysis.tg_analysis.temperature_assignment import (    assign_nominal_temperatures,)from iphasimulator.analysis.tg_analysis.optimisation import (    optimise_pca_dimensionality,    calculate_optimised_pca,    optimise_dbscan,)from iphasimulator.analysis.tg_analysis.clustering import (    cluster_all_chain_pca,)from iphasimulator.analysis.tg_analysis.glass_transition import (    calculate_historical_cluster_response,    fit_historical_tg,)# =============================================================================# General figure helper# =============================================================================def _save_figure(    figure,    output_path,    dpi=300,):    """    Save and close a matplotlib figure.    """    output_path = Path(        output_path    )    output_path.parent.mkdir(        parents=True,        exist_ok=True,    )    figure.tight_layout()    figure.savefig(        output_path,        dpi=dpi,        bbox_inches="tight",    )    plt.close(        figure    )# =============================================================================# Temperature figure# =============================================================================def plot_temperature_block_agreement(    temperatures,    simulation_data,    output_path,):    """    Plot nominal temperature against mean recorded temperature.    Error bars represent the standard deviation of the instantaneous    recorded temperature within each nominal temperature block.    """    required_column = (        "Temperature (K)"    )    if (        required_column        not in simulation_data.columns    ):        print(            "WARNING: temperature_block_agreement.png "            "was not generated because the state-data "            "file does not contain 'Temperature (K)'."        )        return False    comparison = (        temperatures[            [                "Nominal Temperature (K)"            ]        ]        .copy()    )    comparison[        "Recorded Temperature (K)"    ] = (        simulation_data[            required_column        ]        .to_numpy()    )    block_statistics = (        comparison        .groupby(            "Nominal Temperature (K)",            as_index=False,        )        .agg(            Mean_Recorded_Temperature=(                "Recorded Temperature (K)",                "mean",            ),            Temperature_SD=(                "Recorded Temperature (K)",                "std",            ),        )        .sort_values(            "Nominal Temperature (K)"        )    )    figure, axis = plt.subplots(        figsize=(7, 6)    )    axis.errorbar(        block_statistics[            "Nominal Temperature (K)"        ],        block_statistics[            "Mean_Recorded_Temperature"        ],        yerr=block_statistics[            "Temperature_SD"        ],        marker="o",        linestyle="none",        capsize=2,        label="Recorded block mean ± SD",    )    temperature_min = min(        block_statistics[            "Nominal Temperature (K)"        ].min(),        block_statistics[            "Mean_Recorded_Temperature"        ].min(),    )    temperature_max = max(        block_statistics[            "Nominal Temperature (K)"        ].max(),        block_statistics[            "Mean_Recorded_Temperature"        ].max(),    )    axis.plot(        [            temperature_min,            temperature_max,        ],        [            temperature_min,            temperature_max,        ],        linestyle="--",        label="Ideal agreement",    )    axis.set_xlabel(        "Nominal temperature (K)"    )    axis.set_ylabel(        "Mean recorded temperature (K)"    )    axis.set_title(        "Temperature-block agreement"    )    axis.legend()    _save_figure(        figure,        output_path,    )    return True# =============================================================================# PCA scree figure# =============================================================================def plot_pca_scree(    pca_optimisation,    output_path,):    """    Plot the median PCA scree curve across polymer chains.    The interquartile range across chains is shown as a shaded region.    """    spectra = (        pca_optimisation        .spectra_dataframe        .copy()    )    summary = (        spectra        .groupby(            "PC",            as_index=False,        )        .agg(            Median=(                "Explained Variance",                "median",            ),            Q1=(                "Explained Variance",                lambda values:                    values.quantile(0.25),            ),            Q3=(                "Explained Variance",                lambda values:                    values.quantile(0.75),            ),        )    )    figure, axis = plt.subplots(        figsize=(7, 5)    )    axis.plot(        summary["PC"],        summary["Median"] * 100,        marker="o",        label="Median spectrum",    )    axis.fill_between(        summary["PC"],        summary["Q1"] * 100,        summary["Q3"] * 100,        alpha=0.25,        label="Chain Q1–Q3",    )    axis.axvline(        pca_optimisation.selected_components,        linestyle="--",        label=(            "Selected PCs = "            f"{pca_optimisation.selected_components}"        ),    )    axis.set_xlabel(        "Principal component"    )    axis.set_ylabel(        "Explained variance (%)"    )    axis.set_title(        "PCA scree analysis"    )    axis.legend()    _save_figure(        figure,        output_path,    )# =============================================================================# PCA elbow distribution# =============================================================================def plot_pca_elbow_distribution(    pca_optimisation,    output_path,):    """    Plot the distribution of PCA elbow positions across polymer chains.    """    elbows = (        pca_optimisation        .dimensionality_dataframe[            "Elbow PC"        ]        .dropna()        .astype(int)        .to_numpy()    )    if len(elbows) == 0:        print(            "WARNING: no PCA elbows available; "            "PCA elbow figure skipped."        )        return False    minimum = int(        elbows.min()    )    maximum = int(        elbows.max()    )    bins = np.arange(        minimum - 0.5,        maximum + 1.5,        1,    )    figure, axis = plt.subplots(        figsize=(7, 5)    )    axis.hist(        elbows,        bins=bins,        edgecolor="black",    )    axis.axvline(        pca_optimisation.selected_components,        linestyle="--",        linewidth=2,        label=(            "Selected PCs = "            f"{pca_optimisation.selected_components}"        ),    )    axis.set_xlabel(        "PCA elbow position"    )    axis.set_ylabel(        "Number of polymer chains"    )    axis.set_title(        "Distribution of chain-level PCA elbows"    )    axis.set_xticks(        np.arange(            minimum,            maximum + 1,        )    )    axis.legend()    _save_figure(        figure,        output_path,    )    return True# =============================================================================# DBSCAN summary helper# =============================================================================def _summarise_dbscan_parameter(    parameter_dataframe,    value_column,):    """    Calculate median and IQR across chains for one DBSCAN diagnostic.    """    return (        parameter_dataframe        .groupby(            "Min Samples",            as_index=False,        )        .agg(            Median=(                value_column,                "median",            ),            Q1=(                value_column,                lambda values:                    values.quantile(0.25),            ),            Q3=(                value_column,                lambda values:                    values.quantile(0.75),            ),        )    )# =============================================================================# DBSCAN noise figure# =============================================================================def plot_dbscan_noise(    dbscan_optimisation,    output_path,):    """    Plot DBSCAN noise fraction against min_samples.    """    summary = (        _summarise_dbscan_parameter(            dbscan_optimisation            .parameter_dataframe,            "Noise Fraction",        )    )    figure, axis = plt.subplots(        figsize=(7, 5)    )    axis.plot(        summary["Min Samples"],        summary["Median"] * 100,        marker="o",        label="Median noise fraction",    )    axis.fill_between(        summary["Min Samples"],        summary["Q1"] * 100,        summary["Q3"] * 100,        alpha=0.25,        label="Chain Q1–Q3",    )    axis.axvline(        dbscan_optimisation        .selected_min_samples,        linestyle="--",        label=(            "Selected min_samples = "            f"{dbscan_optimisation.selected_min_samples}"        ),    )    axis.set_xlabel(        "DBSCAN min_samples"    )    axis.set_ylabel(        "Noise fraction (%)"    )    axis.set_title(        "DBSCAN noise sensitivity"    )    axis.legend()    _save_figure(        figure,        output_path,    )# =============================================================================# DBSCAN cluster-count figure# =============================================================================def plot_dbscan_clusters(    dbscan_optimisation,    output_path,):    """    Plot the number of DBSCAN clusters against min_samples.    """    summary = (        _summarise_dbscan_parameter(            dbscan_optimisation            .parameter_dataframe,            "Clusters",        )    )    figure, axis = plt.subplots(        figsize=(7, 5)    )    axis.plot(        summary["Min Samples"],        summary["Median"],        marker="o",        label="Median clusters",    )    axis.fill_between(        summary["Min Samples"],        summary["Q1"],        summary["Q3"],        alpha=0.25,        label="Chain Q1–Q3",    )    axis.axvline(        dbscan_optimisation        .selected_min_samples,        linestyle="--",        label=(            "Selected min_samples = "            f"{dbscan_optimisation.selected_min_samples}"        ),    )    axis.set_xlabel(        "DBSCAN min_samples"    )    axis.set_ylabel(        "Number of clusters"    )    axis.set_title(        "DBSCAN cluster-count sensitivity"    )    axis.legend()    _save_figure(        figure,        output_path,    )# =============================================================================# DBSCAN ARI figure# =============================================================================def plot_dbscan_ari(    dbscan_optimisation,    output_path,):    """    Plot adjacent-min_samples Adjusted Rand Index stability.    """    stability = (        dbscan_optimisation        .stability_dataframe        .copy()    )    if (        stability.empty        or "ARI All"        not in stability.columns    ):        print(            "WARNING: DBSCAN ARI figure skipped "            "because no ARI stability data are available."        )        return False    summary = (        stability        .groupby(            "Min Samples",            as_index=False,        )        .agg(            Median=(                "ARI All",                "median",            ),            Q1=(                "ARI All",                lambda values:                    values.quantile(0.25),            ),            Q3=(                "ARI All",                lambda values:                    values.quantile(0.75),            ),        )    )    figure, axis = plt.subplots(        figsize=(7, 5)    )    axis.plot(        summary["Min Samples"],        summary["Median"],        marker="o",        label="Median adjacent ARI",    )    axis.fill_between(        summary["Min Samples"],        summary["Q1"],        summary["Q3"],        alpha=0.25,        label="Chain Q1–Q3",    )    axis.axvline(        dbscan_optimisation        .selected_min_samples,        linestyle="--",        label=(            "Selected min_samples = "            f"{dbscan_optimisation.selected_min_samples}"        ),    )    axis.set_xlabel(        "DBSCAN min_samples"    )    axis.set_ylabel(        "Adjusted Rand Index"    )    axis.set_title(        "DBSCAN adjacent-parameter stability"    )    axis.set_ylim(        -0.05,        1.05,    )    axis.legend()    _save_figure(        figure,        output_path,    )    return True# =============================================================================# Historical Tg model# =============================================================================def _historical_tg_model(    temperature,    C,    s,    d,):    """    Evaluate the historical hyperbolic-tangent Tg response model.    g(T) = C/2 * (1 - tanh(sT - d)) - 1    Tg = d / s    """    temperature = np.asarray(        temperature,        dtype=float,    )    return (        (C / 2.0)        * (            1.0            - np.tanh(                s * temperature                - d            )        )        - 1.0    )# =============================================================================# Tg fit figure# =============================================================================def plot_tg_fit(    temperature_response,    tg_result,    system_name,    simulation_name,    output_path,):    """    Plot the historical temperature response and fitted Tg model.    """    temperatures = np.asarray(        temperature_response        .temperatures,        dtype=float,    )    response = np.asarray(        temperature_response        .response,        dtype=float,    )    sort_order = np.argsort(        temperatures    )    temperatures = temperatures[        sort_order    ]    response = response[        sort_order    ]    fit_temperatures = np.linspace(        temperatures.min(),        temperatures.max(),        500,    )    fitted_response = (        _historical_tg_model(            fit_temperatures,            tg_result.C,            tg_result.s,            tg_result.d,        )    )    figure, axis = plt.subplots(        figsize=(8, 5)    )    axis.scatter(        temperatures,        response,        label="Temperature response",    )    axis.plot(        fit_temperatures,        fitted_response,        linewidth=2,        label="Hyperbolic-tangent fit",    )    axis.axvline(        tg_result.tg,        linestyle="--",        linewidth=2,        label=(            f"Tg = {tg_result.tg:.2f} K"        ),    )    axis.set_xlabel(        "Temperature (K)"    )    axis.set_ylabel(        "Mean DBSCAN cluster-label response"    )    axis.set_title(        f"{system_name} | {simulation_name}"    )    axis.legend()    _save_figure(        figure,        output_path,    )# =============================================================================# Replica conformational-state table# =============================================================================def build_conformational_state_dataframe(    all_descriptors,    pca_results,    clustering_results,    temperature_assignment,):    """    Build a reusable chain/frame-level conformational-state table.    One row corresponds to one sampled trajectory frame for one polymer    chain.    Columns include:    - chain analysis identifier    - original topology segid, where available    - trajectory frame    - nominal temperature    - all selected principal components    - final DBSCAN label    - DBSCAN noise status    Notes    -----    PCA is performed independently for each polymer chain. Consequently,    PC coordinates belonging to different chains should not automatically    be interpreted as sharing a common PCA basis.    """    temperature_column = (        "Nominal Temperature (K)"    )    records = []    for (        chain_id,        descriptor_result,    ) in all_descriptors.items():        if chain_id not in pca_results:            raise KeyError(                f"PCA results are missing for "                f"chain '{chain_id}'."            )        if chain_id not in clustering_results:            raise KeyError(                f"DBSCAN results are missing for "                f"chain '{chain_id}'."            )        pca_result = (            pca_results[                chain_id            ]        )        clustering_result = (            clustering_results[                chain_id            ]        )        frame_indices = np.asarray(            descriptor_result.frame_indices,            dtype=int,        )        transformed_data = np.asarray(            pca_result.transformed_data,            dtype=float,        )        labels = np.asarray(            clustering_result.labels,            dtype=int,        )        n_samples = len(            frame_indices        )        if transformed_data.shape[0] != n_samples:            raise ValueError(                f"PCA/frame count mismatch for "                f"{chain_id}:\n"                f"Frames: {n_samples}\n"                f"PCA rows: {transformed_data.shape[0]}"            )        if len(labels) != n_samples:            raise ValueError(                f"DBSCAN/frame count mismatch for "                f"{chain_id}:\n"                f"Frames: {n_samples}\n"                f"Labels: {len(labels)}"            )        if frame_indices.max() >= len(            temperature_assignment        ):            raise IndexError(                f"Sampled frame index for {chain_id} "                "exceeds the temperature-assignment table."            )        sampled_temperatures = (            temperature_assignment            .iloc[                frame_indices            ][                temperature_column            ]            .to_numpy(                dtype=float            )        )        topology_segid = getattr(            descriptor_result,            "topology_segid",            None,        )        segment_index = getattr(            descriptor_result,            "segment_index",            None,        )        for sample_index in range(            n_samples        ):            record = {                "Chain":                    chain_id,                "Topology SegID":                    topology_segid,                "Segment Index":                    segment_index,                "Frame":                    int(                        frame_indices[                            sample_index                        ]                    ),                "Temperature (K)":                    float(                        sampled_temperatures[                            sample_index                        ]                    ),                "DBSCAN Label":                    int(                        labels[                            sample_index                        ]                    ),                "DBSCAN Noise":                    bool(                        labels[                            sample_index                        ]                        == -1                    ),            }            for component_index in range(                transformed_data.shape[1]            ):                record[                    f"PC{component_index + 1}"                ] = float(                    transformed_data[                        sample_index,                        component_index,                    ]                )            records.append(                record            )    dataframe = pd.DataFrame(        records    )    if dataframe.empty:        raise RuntimeError(            "Conformational-state table is empty."        )    return dataframe# =============================================================================# Chain-level PCA plotting# =============================================================================def plot_chain_pca_temperature(    chain_dataframe,    pca_result,    chain_id,    output_path,):    """    Plot PC1 versus PC2 for one chain, coloured by nominal temperature.    """    if (        "PC1" not in chain_dataframe.columns        or "PC2" not in chain_dataframe.columns    ):        return False    explained_variance = np.asarray(        pca_result.explained_variance_ratio,        dtype=float,    )    pc1_variance = (        explained_variance[0] * 100        if len(explained_variance) >= 1        else np.nan    )    pc2_variance = (        explained_variance[1] * 100        if len(explained_variance) >= 2        else np.nan    )    figure, axis = plt.subplots(        figsize=(7, 6)    )    scatter = axis.scatter(        chain_dataframe["PC1"],        chain_dataframe["PC2"],        c=chain_dataframe[            "Temperature (K)"        ],        cmap="viridis",        s=10,        alpha=0.7,    )    colourbar = (        figure.colorbar(            scatter,            ax=axis,        )    )    colourbar.set_label(        "Temperature (K)"    )    axis.set_xlabel(        f"PC1 ({pc1_variance:.2f} %)"    )    axis.set_ylabel(        f"PC2 ({pc2_variance:.2f} %)"    )    axis.set_title(        f"{chain_id}: PC1 vs PC2 coloured by temperature"    )    _save_figure(        figure,        output_path,    )    return Truedef plot_chain_pca_dbscan(    chain_dataframe,    pca_result,    chain_id,    output_path,):    """    Plot PC1 versus PC2 for one chain, coloured by final DBSCAN label.    """    if (        "PC1" not in chain_dataframe.columns        or "PC2" not in chain_dataframe.columns    ):        return False    explained_variance = np.asarray(        pca_result.explained_variance_ratio,        dtype=float,    )    pc1_variance = (        explained_variance[0] * 100        if len(explained_variance) >= 1        else np.nan    )    pc2_variance = (        explained_variance[1] * 100        if len(explained_variance) >= 2        else np.nan    )    figure, axis = plt.subplots(        figsize=(7, 6)    )    unique_labels = sorted(        chain_dataframe[            "DBSCAN Label"        ]        .unique()    )    for label in unique_labels:        label_data = (            chain_dataframe[                chain_dataframe[                    "DBSCAN Label"                ]                == label            ]        )        if label == -1:            display_label = (                "Noise (-1)"            )        else:            display_label = (                f"Cluster {label}"            )        axis.scatter(            label_data["PC1"],            label_data["PC2"],            s=10,            alpha=0.7,            label=display_label,        )    axis.set_xlabel(        f"PC1 ({pc1_variance:.2f} %)"    )    axis.set_ylabel(        f"PC2 ({pc2_variance:.2f} %)"    )    axis.set_title(        f"{chain_id}: PC1 vs PC2 coloured by DBSCAN state"    )    axis.legend(        markerscale=2,        fontsize="small",    )    _save_figure(        figure,        output_path,    )    return True# =============================================================================# Generate chain-level PCA figure set# =============================================================================def generate_chain_pca_figures(    conformational_state_dataframe,    pca_results,    output_directory,):    """    Generate temperature- and DBSCAN-coloured PCA plots for every chain.    PCA is calculated independently for each chain, so separate figures    are generated rather than pooling chain coordinates into one PCA space.    """    output_directory.mkdir(        parents=True,        exist_ok=True,    )    saved_paths = []    for (        chain_id,        pca_result,    ) in pca_results.items():        chain_dataframe = (            conformational_state_dataframe[                conformational_state_dataframe[                    "Chain"                ]                == chain_id            ]            .copy()        )        if chain_dataframe.empty:            print(                f"WARNING: no conformational-state "                f"data found for {chain_id}."            )            continue        # ---------------------------------------------------------------------        # Temperature-coloured PCA        # ---------------------------------------------------------------------        temperature_path = (            output_directory            / (                f"{chain_id}"                "_pc1_pc2_temperature.png"            )        )        generated = (            plot_chain_pca_temperature(                chain_dataframe=(                    chain_dataframe                ),                pca_result=(                    pca_result                ),                chain_id=(                    chain_id                ),                output_path=(                    temperature_path                ),            )        )        if generated:            saved_paths.append(                temperature_path            )        # ---------------------------------------------------------------------        # DBSCAN-coloured PCA        # ---------------------------------------------------------------------        dbscan_path = (            output_directory            / (                f"{chain_id}"                "_pc1_pc2_dbscan.png"            )        )        generated = (            plot_chain_pca_dbscan(                chain_dataframe=(                    chain_dataframe                ),                pca_result=(                    pca_result                ),                chain_id=(                    chain_id                ),                output_path=(                    dbscan_path                ),            )        )        if generated:            saved_paths.append(                dbscan_path            )    return saved_paths# =============================================================================# Generate complete replica-level figure set# =============================================================================def generate_analysis_figures(    figure_directory,    temperatures,    simulation_data,    pca_optimisation,    pca_results,    dbscan_optimisation,    temperature_response,    tg_result,    conformational_state_dataframe,    system_name,    simulation_name,):    """    Generate the complete replica-level Tg analysis figure set.    """    figure_directory.mkdir(        parents=True,        exist_ok=True,    )    print()    print(        "Generating replica-level analysis figures"    )    print("-" * 80)    figure_paths = []    # -------------------------------------------------------------------------    # Temperature agreement    # -------------------------------------------------------------------------    path = (        figure_directory        / "temperature_block_agreement.png"    )    if plot_temperature_block_agreement(        temperatures=temperatures,        simulation_data=simulation_data,        output_path=path,    ):        figure_paths.append(            path        )    # -------------------------------------------------------------------------    # PCA scree    # -------------------------------------------------------------------------    path = (        figure_directory        / "pca_scree.png"    )    plot_pca_scree(        pca_optimisation=(            pca_optimisation        ),        output_path=(            path        ),    )    figure_paths.append(        path    )    # -------------------------------------------------------------------------    # PCA elbows    # -------------------------------------------------------------------------    path = (        figure_directory        / "pca_elbow_distribution.png"    )    if plot_pca_elbow_distribution(        pca_optimisation=(            pca_optimisation        ),        output_path=(            path        ),    ):        figure_paths.append(            path        )    # -------------------------------------------------------------------------    # DBSCAN ARI    # -------------------------------------------------------------------------    path = (        figure_directory        / "dbscan_ari_vs_min_samples.png"    )    if plot_dbscan_ari(        dbscan_optimisation=(            dbscan_optimisation        ),        output_path=(            path        ),    ):        figure_paths.append(            path        )    # -------------------------------------------------------------------------    # DBSCAN noise    # -------------------------------------------------------------------------    path = (        figure_directory        / "dbscan_noise_vs_min_samples.png"    )    plot_dbscan_noise(        dbscan_optimisation=(            dbscan_optimisation        ),        output_path=(            path        ),    )    figure_paths.append(        path    )    # -------------------------------------------------------------------------    # DBSCAN clusters    # -------------------------------------------------------------------------    path = (        figure_directory        / "dbscan_clusters_vs_min_samples.png"    )    plot_dbscan_clusters(        dbscan_optimisation=(            dbscan_optimisation        ),        output_path=(            path        ),    )    figure_paths.append(        path    )    # -------------------------------------------------------------------------    # Tg fit    # -------------------------------------------------------------------------    path = (        figure_directory        / "tg_fit.png"    )    plot_tg_fit(        temperature_response=(            temperature_response        ),        tg_result=(            tg_result        ),        system_name=(            system_name        ),        simulation_name=(            simulation_name        ),        output_path=(            path        ),    )    figure_paths.append(        path    )    # -------------------------------------------------------------------------    # Per-chain PCA figures    # -------------------------------------------------------------------------    chain_pca_directory = (        figure_directory        / "pca_by_chain"    )    chain_paths = (        generate_chain_pca_figures(            conformational_state_dataframe=(                conformational_state_dataframe            ),            pca_results=(                pca_results            ),            output_directory=(                chain_pca_directory            ),        )    )    figure_paths.extend(        chain_paths    )    print(        f"Generated "        f"{len(figure_paths)} figures."    )    return figure_paths# =============================================================================# Human-readable report# =============================================================================def write_analysis_report(    output_path,    system_name,    simulation_name,    stage,    loaded_simulation,    analysis_stride,    temperatures,    all_descriptors,    pca_optimisation,    dbscan_optimisation,    selected_dbscan_dataframe,    tg_result,    conformational_state_dataframe,):    """    Write a concise human-readable replica-level Tg analysis report.    """    median_epsilon = float(        selected_dbscan_dataframe[            "Epsilon"        ].median()    )    median_clusters = float(        selected_dbscan_dataframe[            "Clusters"        ].median()    )    median_noise = float(        selected_dbscan_dataframe[            "Noise Fraction"        ].median()    )    example_chain = next(        iter(            all_descriptors.values()        )    )    lines = [        "=" * 80,        "REPLICA Tg ANALYSIS REPORT",        "=" * 80,        "",        "SYSTEM",        "-" * 80,        f"System: {system_name}",        f"Simulation: {simulation_name}",        f"Stage: {stage}",        (            "Topology: "            f"{loaded_simulation.topology_path.name}"        ),        (            "Trajectory: "            f"{loaded_simulation.trajectory_path.name}"        ),        (            "Trajectory frames: "            f"{len(loaded_simulation.universe.trajectory)}"        ),        (            "Polymer chains analysed: "            f"{len(all_descriptors)}"        ),        "",        "TEMPERATURE ASSIGNMENT",        "-" * 80,        (            "Temperature blocks: "            f"{temperatures['Nominal Temperature (K)'].nunique()}"        ),        (            "Maximum nominal temperature: "            f"{temperatures['Nominal Temperature (K)'].max():.1f} K"        ),        (            "Minimum nominal temperature: "            f"{temperatures['Nominal Temperature (K)'].min():.1f} K"        ),        "",        "STRUCTURAL DESCRIPTORS",        "-" * 80,        (            "Sampling stride: "            f"{analysis_stride}"        ),        (            "Frames analysed per chain: "            f"{len(example_chain.frame_indices)}"        ),        (            "Heavy atoms per example chain: "            f"{example_chain.n_heavy_atoms}"        ),        (            "Distances per conformation: "            f"{example_chain.descriptors.shape[1]}"        ),        "",        "PCA",        "-" * 80,        (            "Selected PCs: "            f"{pca_optimisation.selected_components}"        ),        (            "Median PCA elbow: "            f"{pca_optimisation.median_elbow:.3f}"        ),        (            "Mean PCA elbow: "            f"{pca_optimisation.mean_elbow:.3f}"        ),        (            "PCA elbow Q1-Q3: "            f"{pca_optimisation.elbow_q1:.3f}"            " - "            f"{pca_optimisation.elbow_q3:.3f}"        ),        (            "Chains within ±1 PC: "            f"{pca_optimisation.fraction_within_one_component * 100:.2f} %"        ),        "",        "DBSCAN",        "-" * 80,        (            "Neighbour rank k: "            f"{dbscan_optimisation.k}"        ),        (            "Selected min_samples: "            f"{dbscan_optimisation.selected_min_samples}"        ),        (            "Median epsilon: "            f"{median_epsilon:.6f}"        ),        (            "Median clusters: "            f"{median_clusters:.3f}"        ),        (            "Median noise fraction: "            f"{median_noise:.6f}"        ),        "",        "CONFORMATIONAL STATE TABLE",        "-" * 80,        (            "Rows: "            f"{len(conformational_state_dataframe)}"        ),        (            "Columns: "            f"{len(conformational_state_dataframe.columns)}"        ),        "",        "GLASS TRANSITION",        "-" * 80,        (            "Observable: "            "historical_mean_dbscan_cluster_id"        ),        (            "Estimated Tg: "            f"{tg_result.tg:.2f} K"        ),        (            "C: "            f"{tg_result.C:.6f}"        ),        (            "s: "            f"{tg_result.s:.6f}"        ),        (            "d: "            f"{tg_result.d:.6f}"        ),        "",        "=" * 80,    ]    output_path.write_text(        "\n".join(            lines        ),        encoding="utf-8",    )# =============================================================================# Main replica workflow# =============================================================================def run_tg_analysis(    system_name,    simulation_name,    stage="thermal_ramp_cooling",    total_steps=200_000_000,    max_temp=700,    min_temp=140,    temp_change=10,    reporter_freq=1000,    analysis_stride=50,    max_pca_components=20,    dbscan_min_samples_values=range(2, 11),    generate_figures=False,    project_root=None,):    """    Run the complete Tg analysis for one simulation replica.    Parameters    ----------    system_name : str        MD system name.    simulation_name : str        Name of the completed simulation / replica.    stage : str, optional        Simulation stage to analyse.    total_steps : int, optional        Total integration steps in the thermal ramp.    max_temp : float, optional        Maximum cooling-ramp temperature in kelvin.    min_temp : float, optional        Minimum cooling-ramp temperature in kelvin.    temp_change : float, optional        Temperature step between nominal temperature blocks.    reporter_freq : int, optional        Reporter frequency in MD integration steps.    analysis_stride : int, optional        Trajectory frame sampling stride.    max_pca_components : int, optional        Maximum PCA dimensionality considered during optimisation.    dbscan_min_samples_values : iterable of int, optional        Candidate DBSCAN min_samples values.    generate_figures : bool, optional        Generate replica-level diagnostic figures and text report.        Default:            False    project_root : str or pathlib.Path, optional        iPHAsimulatorV2 project root.    Returns    -------    dict        Completed replica-level analysis summary.    """    # =========================================================================    # Resolve project paths    # =========================================================================    if project_root is None:        project_root = (            Path(__file__)            .resolve()            .parents[4]        )    else:        project_root = (            Path(project_root)            .expanduser()            .resolve()        )    structure_database = (        project_root        / "structure_database"    )    system_directory = (        structure_database        / "PHA_melts"        / system_name    )    simulation_directory = (        system_directory        / "simulations"        / simulation_name    )    # =========================================================================    # Replica-level analysis directory    # =========================================================================    analysis_directory = (        simulation_directory        / "analysis"        / "tg_analysis"    )    pca_directory = (        analysis_directory        / "pca"    )    dbscan_directory = (        analysis_directory        / "dbscan"    )    tg_directory = (        analysis_directory        / "tg"    )    figure_directory = (        analysis_directory        / "figures"    )    report_path = (        analysis_directory        / "tg_analysis_output.txt"    )    # =========================================================================    # Validate paths    # =========================================================================    if not system_directory.is_dir():        raise FileNotFoundError(            "MD system directory was not found:\n"            f"{system_directory}"        )    if not simulation_directory.is_dir():        raise FileNotFoundError(            "Simulation directory was not found:\n"            f"{simulation_directory}"        )    for directory in (        analysis_directory,        pca_directory,        dbscan_directory,        tg_directory,    ):        directory.mkdir(            parents=True,            exist_ok=True,        )    # =========================================================================    # Header    # =========================================================================    print()    print("=" * 80)    print("REPLICA Tg ANALYSIS WORKFLOW")    print("=" * 80)    print(        f"System:      {system_name}"    )    print(        f"Simulation:  {simulation_name}"    )    print(        f"Stage:       {stage}"    )    print(        f"Input:       {simulation_directory}"    )    print(        f"Output:      {analysis_directory}"    )    print(        f"Figures:     {generate_figures}"    )    print("=" * 80)    # =========================================================================    # STEP 1    # Load simulation    # =========================================================================    print()    print(        "Step 1: loading simulation"    )    print("-" * 80)    loaded_simulation = (        load_simulation(            system_directory=(                system_directory            ),            simulation_name=(                simulation_name            ),            stage=(                stage            ),            validate_alignment=True,        )    )    universe = (        loaded_simulation.universe    )    simulation_data = (        loaded_simulation.data    )    print(        f"Topology:    "        f"{loaded_simulation.topology_path.name}"    )    print(        f"Trajectory:  "        f"{loaded_simulation.trajectory_path.name}"    )    print(        f"State data:  "        f"{loaded_simulation.data_path.name}"    )    print(        f"Atoms:       "        f"{universe.atoms.n_atoms}"    )    print(        f"Residues:    "        f"{universe.residues.n_residues}"    )    print(        f"Segments:    "        f"{universe.segments.n_segments}"    )    print(        f"Frames:      "        f"{len(universe.trajectory)}"    )    print(        f"Data rows:   "        f"{len(simulation_data)}"    )    print(        "Trajectory/state-data alignment: OK"    )    # =========================================================================    # STEP 2    # Assign temperatures    # =========================================================================    print()    print(        "Step 2: assigning temperatures"    )    print("-" * 80)    temperatures = (        assign_nominal_temperatures(            simulation=(                loaded_simulation            ),            total_steps=(                total_steps            ),            max_temp=(                max_temp            ),            min_temp=(                min_temp            ),            temp_change=(                temp_change            ),            reporter_freq=(                reporter_freq            ),        )    )    temperature_column = (        "Nominal Temperature (K)"    )    if len(temperatures) != len(        universe.trajectory    ):        raise ValueError(            "Temperature assignment does not match trajectory length:\n"            f"Trajectory frames:       {len(universe.trajectory)}\n"            f"Temperature assignments: {len(temperatures)}"        )    if temperatures[        temperature_column    ].isna().any():        raise ValueError(            "Temperature assignment contains missing nominal temperatures."        )    first_temperature = float(        temperatures[            temperature_column        ].iloc[0]    )    final_temperature = float(        temperatures[            temperature_column        ].iloc[-1]    )    if first_temperature != float(        max_temp    ):        raise ValueError(            "Unexpected starting nominal temperature:\n"            f"Expected: {max_temp} K\n"            f"Found:    {first_temperature} K"        )    if final_temperature != float(        min_temp    ):        raise ValueError(            "Unexpected final nominal temperature:\n"            f"Expected: {min_temp} K\n"            f"Found:    {final_temperature} K"        )    n_temperature_blocks = int(        temperatures[            temperature_column        ].nunique()    )    print(        f"Maximum temperature:   "        f"{max_temp} K"    )    print(        f"Minimum temperature:   "        f"{min_temp} K"    )    print(        f"Temperature step:      "        f"{temp_change} K"    )    print(        f"Temperature blocks:    "        f"{n_temperature_blocks}"    )    print(        f"Assigned frames:       "        f"{len(temperatures)}"    )    print(        "Temperature assignment: OK"    )    # =========================================================================    # STEP 3    # Structural descriptors    # =========================================================================    print()    print(        "Step 3: generating structural descriptors"    )    print("-" * 80)    print(        f"Sampling stride: "        f"{analysis_stride}"    )    all_descriptors = (        calculate_all_chain_distance_descriptors(            simulation=(                loaded_simulation            ),            stride=(                analysis_stride            ),        )    )    if not all_descriptors:        raise RuntimeError(            "No structural descriptors were generated."        )    example_chain = next(        iter(            all_descriptors.values()        )    )    print(        f"Polymer chains analysed: "        f"{len(all_descriptors)}"    )    print(        f"Frames per chain: "        f"{len(example_chain.frame_indices)}"    )    print(        f"Descriptor matrix per chain: "        f"{example_chain.descriptors.shape}"    )    print(        f"Heavy atoms per chain: "        f"{example_chain.n_heavy_atoms}"    )    print(        f"Distances per conformation: "        f"{example_chain.descriptors.shape[1]}"    )    # =========================================================================    # STEP 4    # PCA dimensionality optimisation    # =========================================================================    print()    print(        "Step 4: optimising PCA dimensionality"    )    print("-" * 80)    pca_optimisation = (        optimise_pca_dimensionality(            descriptors_by_segment=(                all_descriptors            ),            max_components=(                max_pca_components            ),        )    )    print(        f"Selected PCs: "        f"{pca_optimisation.selected_components}"    )    print(        f"Median elbow: "        f"{pca_optimisation.median_elbow:.3f}"    )    print(        f"Mean elbow: "        f"{pca_optimisation.mean_elbow:.3f}"    )    print(        f"Elbow Q1-Q3: "        f"{pca_optimisation.elbow_q1:.3f}"        " - "        f"{pca_optimisation.elbow_q3:.3f}"    )    print(        f"Chains within ±1 PC: "        f"{pca_optimisation.fraction_within_one_component * 100:.2f} %"    )    # =========================================================================    # STEP 5    # Final PCA representation    # =========================================================================    print()    print(        "Step 5: calculating final PCA representation"    )    print("-" * 80)    pca_results = (        calculate_optimised_pca(            descriptors_by_segment=(                all_descriptors            ),            optimisation_result=(                pca_optimisation            ),        )    )    if not pca_results:        raise RuntimeError(            "No PCA results were generated."        )    if (        pca_optimisation        .selected_components        < 2    ):        print(            "WARNING: fewer than two PCs were selected. "            "PC1-vs-PC2 figures cannot be generated."        )    print(        f"Selected dimensionality: "        f"{pca_optimisation.selected_components} PCs"    )    print(        f"Polymer chains transformed: "        f"{len(pca_results)}"    )    # =========================================================================    # STEP 6    # DBSCAN optimisation    # =========================================================================    print()    print(        "Step 6: optimising DBSCAN"    )    print("-" * 80)    dbscan_optimisation = (        optimise_dbscan(            pca_results=(                pca_results            ),            min_samples_values=(                dbscan_min_samples_values            ),            n_temperatures=(                n_temperature_blocks            ),        )    )    selected_min_samples = (        dbscan_optimisation        .selected_min_samples    )    selected_k = (        dbscan_optimisation        .k    )    print(        f"PCA dimensions:      "        f"{dbscan_optimisation.n_components}"    )    print(        f"Neighbour rank k:     "        f"{selected_k}"    )    print(        f"Selected min_samples: "        f"{selected_min_samples}"    )    # =========================================================================    # STEP 7    # Final DBSCAN clustering    # =========================================================================    print()    print(        "Step 7: performing final DBSCAN clustering"    )    print("-" * 80)    clustering_results = (        cluster_all_chain_pca(            pca_results=(                pca_results            ),            k=(                selected_k            ),            min_samples=(                selected_min_samples            ),            n_temperatures=(                n_temperature_blocks            ),        )    )    if not clustering_results:        raise RuntimeError(            "No DBSCAN clustering results were generated."        )    print(        f"Chains clustered: "        f"{len(clustering_results)}"    )    # =========================================================================    # STEP 8    # Temperature response    # =========================================================================    print()    print(        "Step 8: constructing temperature response"    )    print("-" * 80)    temperature_response = (        calculate_historical_cluster_response(            clustering_results=(                clustering_results            ),            temperature_assignment=(                temperatures            ),        )    )    print(        f"Temperature response points: "        f"{len(temperature_response.temperatures)}"    )    # =========================================================================    # STEP 9    # Tg fitting    # =========================================================================    print()    print(        "Step 9: fitting glass transition"    )    print("-" * 80)    tg_result = (        fit_historical_tg(            temperature_response        )    )    print(        f"Tg: {tg_result.tg:.2f} K"    )    print(        f"C:  {tg_result.C:.6f}"    )    print(        f"s:  {tg_result.s:.6f}"    )    print(        f"d:  {tg_result.d:.6f}"    )    # =========================================================================    # STEP 10    # Build conformational-state table    # =========================================================================    print()    print(        "Step 10: building conformational-state table"    )    print("-" * 80)    conformational_state_dataframe = (        build_conformational_state_dataframe(            all_descriptors=(                all_descriptors            ),            pca_results=(                pca_results            ),            clustering_results=(                clustering_results            ),            temperature_assignment=(                temperatures            ),        )    )    print(        f"Conformational-state rows: "        f"{len(conformational_state_dataframe)}"    )    print(        f"Conformational-state columns: "        f"{len(conformational_state_dataframe.columns)}"    )    # =========================================================================    # STEP 11    # Save machine-readable outputs    # =========================================================================    print()    print(        "Step 11: saving replica analysis outputs"    )    print("-" * 80)    # -------------------------------------------------------------------------    # Temperature assignment    # -------------------------------------------------------------------------    temperatures.to_csv(        analysis_directory        / "temperature_assignment.csv",        index=False,    )    # -------------------------------------------------------------------------    # Conformational-state table    # -------------------------------------------------------------------------    conformational_state_path = (        analysis_directory        / "conformational_state_by_chain.csv"    )    conformational_state_dataframe.to_csv(        conformational_state_path,        index=False,    )    # -------------------------------------------------------------------------    # PCA diagnostics    # -------------------------------------------------------------------------    (        pca_optimisation        .dimensionality_dataframe        .to_csv(            pca_directory            / "pca_dimensionality_by_chain.csv",            index=False,        )    )    (        pca_optimisation        .spectra_dataframe        .to_csv(            pca_directory            / "pca_spectrum_by_chain.csv",            index=False,        )    )    # -------------------------------------------------------------------------    # DBSCAN diagnostics    # -------------------------------------------------------------------------    (        dbscan_optimisation        .parameter_dataframe        .to_csv(            dbscan_directory            / "dbscan_parameters.csv",            index=False,        )    )    (        dbscan_optimisation        .stability_dataframe        .to_csv(            dbscan_directory            / "dbscan_stability.csv",            index=False,        )    )    (        dbscan_optimisation        .summary_dataframe        .to_csv(            dbscan_directory            / "dbscan_stability_summary.csv",            index=False,        )    )    # -------------------------------------------------------------------------    # Temperature response    # -------------------------------------------------------------------------    temperature_response_dataframe = (        pd.DataFrame(            {                "Temperature (K)":                    temperature_response                    .temperatures,                "Response":                    temperature_response                    .response,                "Count":                    temperature_response                    .counts,            }        )    )    temperature_response_dataframe.to_csv(        tg_directory        / "temperature_response.csv",        index=False,    )    # -------------------------------------------------------------------------    # Selected DBSCAN statistics    # -------------------------------------------------------------------------    selected_dbscan_dataframe = (        dbscan_optimisation        .parameter_dataframe[            dbscan_optimisation            .parameter_dataframe[                "Min Samples"            ]            == selected_min_samples        ]        .copy()    )    median_epsilon = float(        selected_dbscan_dataframe[            "Epsilon"        ].median()    )    mean_epsilon = float(        selected_dbscan_dataframe[            "Epsilon"        ].mean()    )    median_clusters = float(        selected_dbscan_dataframe[            "Clusters"        ].median()    )    mean_clusters = float(        selected_dbscan_dataframe[            "Clusters"        ].mean()    )    median_noise_fraction = float(        selected_dbscan_dataframe[            "Noise Fraction"        ].median()    )    mean_noise_fraction = float(        selected_dbscan_dataframe[            "Noise Fraction"        ].mean()    )    # -------------------------------------------------------------------------    # Analysis summary    # -------------------------------------------------------------------------    analysis_summary = {        "analysis_level":            "replica",        "system":            system_name,        "simulation":            simulation_name,        "stage":            stage,        "sampling": {            "stride":                int(                    analysis_stride                ),            "trajectory_frames":                int(                    len(                        universe.trajectory                    )                ),            "frames_per_chain":                int(                    len(                        example_chain.frame_indices                    )                ),            "polymer_chains":                int(                    len(                        all_descriptors                    )                ),        },        "temperature_assignment": {            "total_steps":                int(                    total_steps                ),            "reporter_frequency":                int(                    reporter_freq                ),            "max_temperature_K":                float(                    max_temp                ),            "min_temperature_K":                float(                    min_temp                ),            "temperature_change_K":                float(                    temp_change                ),            "n_temperature_blocks":                int(                    n_temperature_blocks                ),        },        "pca": {            "selected_components":                int(                    pca_optimisation                    .selected_components                ),            "median_elbow":                float(                    pca_optimisation                    .median_elbow                ),            "mean_elbow":                float(                    pca_optimisation                    .mean_elbow                ),            "elbow_q1":                float(                    pca_optimisation                    .elbow_q1                ),            "elbow_q3":                float(                    pca_optimisation                    .elbow_q3                ),            "elbow_iqr":                float(                    pca_optimisation                    .elbow_iqr                ),            "fraction_within_one_component":                float(                    pca_optimisation                    .fraction_within_one_component                ),        },        "dbscan": {            "k":                int(                    selected_k                ),            "selected_min_samples":                int(                    selected_min_samples                ),            "median_epsilon":                median_epsilon,            "mean_epsilon":                mean_epsilon,            "median_clusters":                median_clusters,            "mean_clusters":                mean_clusters,            "median_noise_fraction":                median_noise_fraction,            "mean_noise_fraction":                mean_noise_fraction,        },        "tg": {            "observable":                "historical_mean_dbscan_cluster_id",            "tg_K":                float(                    tg_result.tg                ),            "C":                float(                    tg_result.C                ),            "s":                float(                    tg_result.s                ),            "d":                float(                    tg_result.d                ),        },        "outputs": {            "conformational_state_file":                str(                    conformational_state_path                    .relative_to(                        analysis_directory                    )                ),            "temperature_response_file":                str(                    (                        tg_directory                        / "temperature_response.csv"                    )                    .relative_to(                        analysis_directory                    )                ),        },        "figures_generated":            bool(                generate_figures            ),    }    summary_path = (        analysis_directory        / "analysis_summary.json"    )    with open(        summary_path,        "w",        encoding="utf-8",    ) as handle:        json.dump(            analysis_summary,            handle,            indent=4,        )    # =========================================================================    # STEP 12    # Optional figures and report    # =========================================================================    figure_paths = []    if generate_figures:        print()        print(            "Step 12: generating replica figures and report"        )        print("-" * 80)        figure_paths = (            generate_analysis_figures(                figure_directory=(                    figure_directory                ),                temperatures=(                    temperatures                ),                simulation_data=(                    simulation_data                ),                pca_optimisation=(                    pca_optimisation                ),                pca_results=(                    pca_results                ),                dbscan_optimisation=(                    dbscan_optimisation                ),                temperature_response=(                    temperature_response                ),                tg_result=(                    tg_result                ),                conformational_state_dataframe=(                    conformational_state_dataframe                ),                system_name=(                    system_name                ),                simulation_name=(                    simulation_name                ),            )        )        write_analysis_report(            output_path=(                report_path            ),            system_name=(                system_name            ),            simulation_name=(                simulation_name            ),            stage=(                stage            ),            loaded_simulation=(                loaded_simulation            ),            analysis_stride=(                analysis_stride            ),            temperatures=(                temperatures            ),            all_descriptors=(                all_descriptors            ),            pca_optimisation=(                pca_optimisation            ),            dbscan_optimisation=(                dbscan_optimisation            ),            selected_dbscan_dataframe=(                selected_dbscan_dataframe            ),            tg_result=(                tg_result            ),            conformational_state_dataframe=(                conformational_state_dataframe            ),        )        print(            f"Saved report: "            f"{report_path}"        )    # =========================================================================    # Return result    # =========================================================================    result = {        "analysis_level":            "replica",        "system_name":            system_name,        "simulation_name":            simulation_name,        "analysis_directory":            str(                analysis_directory            ),        "analysis_summary_path":            str(                summary_path            ),        "conformational_state_path":            str(                conformational_state_path            ),        "n_chains":            int(                len(                    all_descriptors                )            ),        "analysis_stride":            int(                analysis_stride            ),        "selected_pca_components":            int(                pca_optimisation                .selected_components            ),        "dbscan_k":            int(                selected_k            ),        "dbscan_min_samples":            int(                selected_min_samples            ),        "tg_K":            float(                tg_result.tg            ),        "generate_figures":            bool(                generate_figures            ),        "figure_directory":            (                str(                    figure_directory                )                if generate_figures                else None            ),        "n_figures":            int(                len(                    figure_paths                )            ),        "report_path":            (                str(                    report_path                )                if generate_figures                else None            ),    }    # =========================================================================    # Final report    # =========================================================================    print()    print("=" * 80)    print(        "REPLICA Tg ANALYSIS COMPLETE"    )    print("=" * 80)    print(        f"System:             "        f"{system_name}"    )    print(        f"Simulation:         "        f"{simulation_name}"    )    print(        f"Sampling stride:    "        f"{analysis_stride}"    )    print(        f"Chains analysed:    "        f"{len(all_descriptors)}"    )    print(        f"PCA dimensions:     "        f"{pca_optimisation.selected_components}"    )    print(        f"DBSCAN k:           "        f"{selected_k}"    )    print(        f"DBSCAN min_samples: "        f"{selected_min_samples}"    )    print(        f"Estimated Tg:       "        f"{tg_result.tg:.2f} K"    )    print(        f"Analysis output:    "        f"{analysis_directory}"    )    print(        f"State table:        "        f"{conformational_state_path}"    )    if generate_figures:        print(            f"Figure output:      "            f"{figure_directory}"        )        print(            f"Figures generated:  "            f"{len(figure_paths)}"        )    print("=" * 80)    return result# =============================================================================# Direct execution# =============================================================================if __name__ == "__main__":    # -------------------------------------------------------------------------    # System / simulation    # -------------------------------------------------------------------------    SYSTEM_NAME = (        "25_P3HB_10_melt"    )    SIMULATION_NAME = (        "broad_tg_sim_04"    )    STAGE = (        "thermal_ramp_cooling"    )    # -------------------------------------------------------------------------    # Thermal-ramp settings    # -------------------------------------------------------------------------    TOTAL_STEPS = (        200_000_000    )    MAX_TEMP = (        700    )    MIN_TEMP = (        140    )    TEMP_CHANGE = (        10    )    REPORTER_FREQ = (        1000    )    # -------------------------------------------------------------------------    # Analysis settings    # -------------------------------------------------------------------------    ANALYSIS_STRIDE = (        50    )    MAX_PCA_COMPONENTS = (        20    )    DBSCAN_MIN_SAMPLES_VALUES = (        range(            2,            11,        )    )    # -------------------------------------------------------------------------    # Optional figure generation    # -------------------------------------------------------------------------    GENERATE_FIGURES = (        True    )    # -------------------------------------------------------------------------    # Run replica analysis